def binary_lifting(n, p):
    max_depth = 20  # Assuming log2(n) <= 20
    parent = [[0] * max_depth for _ in range(n + 1)]
    depth = [0] * (n + 1)

    def dfs(node, par):
        parent[node][0] = par
        depth[node] = depth[par] + 1
        for i in range(1, max_depth):
            parent[node][i] = parent[parent[node][i - 1]][i - 1]
        for child in adj_list[node]:
            if child != par:
                dfs(child, node)

    adj_list = [[] for _ in range(n + 1)]
    for i in range(2, n + 1):
        adj_list[p[i]].append(i)

    dfs(1, 0)

    def get_kth_ancestor(node, k):
        for i in range(max_depth):
            if k & (1 << i):
                node = parent[node][i]
        return node

    return parent, depth, get_kth_ancestor

def process_queries(n, q, p, queries, parent, depth, get_kth_ancestor):
    results = []
    for u_i, k_i in queries:
        if k_i > depth[u_i]:
            results.append(-1)
        else:
            ancestor = get_kth_ancestor(u_i, depth[u_i] - k_i)
            results.append(ancestor)
    return results

