def find_kth_officer(root, k):
    queue = deque([root])
    visited = set()
    while queue:
        node = queue.popleft()
        if node not in visited:
            visited.add(node)
            if len(visited) == k:
                return node
            for neighbor in graph[node]:
                if neighbor not in visited:
                    queue.append(neighbor)
